import{_ as r,o as a,c as t,ag as o}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"🔬 科学快报 | 2026年8月13日（事后重建版）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/reconstructed/2026-08-13.md","filePath":"science-log/src/reconstructed/2026-08-13.md"}'),n={name:"science-log/src/reconstructed/2026-08-13.md"};function i(s,e,l,c,g,h){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="🔬-科学快报-2026年8月13日-事后重建版" tabindex="-1">🔬 科学快报 | 2026年8月13日（事后重建版） <a class="header-anchor" href="#🔬-科学快报-2026年8月13日-事后重建版" aria-label="Permalink to &quot;🔬 科学快报 | 2026年8月13日（事后重建版）&quot;">​</a></h1><blockquote><p>⚠️ <strong>事后重建版</strong>：本文件<strong>不是</strong>当日发布原文。由 2026-11-06 依 arXiv / CrossRef <strong>按发布日期回溯检索</strong>生成，选题与排序均为事后判定，<strong>不代表历史原貌</strong>。 取证：CrossRef（Nature 0028-0836 / Science 10.1126 / PNAS 0027-8424）+ arXiv 日期区间 <code>[202608130000 TO 202608132359]</code>（cs.AI）｜ 重建日：2026-11-06 备注：当日 Nature（0028-0836）CrossRef 命中 9 条，其中 <code>10.1038/s41586-…</code> 研究论文仅 2 条且均为 <strong>Author Correction</strong>（更正），故科学 5 篇取自当日 Science（4 篇）与 PNAS（1 篇）。 期号：当日原刊期号无法从本仓库确证 → <strong>（第 ? 期 · 事后重建版）</strong></p></blockquote><h2 id="🔬-科学前沿" tabindex="-1">🔬 科学前沿 <a class="header-anchor" href="#🔬-科学前沿" aria-label="Permalink to &quot;🔬 科学前沿&quot;">​</a></h2><h3 id="🐻-人工冬眠揭示-记忆靠的是「突触印迹架构」而非大树突触" tabindex="-1">🐻 人工冬眠揭示：记忆靠的是「突触印迹架构」而非大树突触 <a class="header-anchor" href="#🐻-人工冬眠揭示-记忆靠的是「突触印迹架构」而非大树突触" aria-label="Permalink to &quot;🐻 人工冬眠揭示：记忆靠的是「突触印迹架构」而非大树突触&quot;">​</a></h3><p><strong>Artificial hibernation reveals synaptic engram architecture associated with memory retention</strong><em>Science（2026-08-13）</em></p><p>小鼠进入人工冬眠后，海马神经元活动大幅下降、树突棘与突触被大量清除，但记忆与相应的海马神经表征依然完好。研究团队（冲绳科学技术大学院大学 Memory Research Unit 等）发现，真正被保留下来的是一类特殊结构：与「多突触 bouton（multisynaptic bouton）」形成连接的树突棘亚群。这推翻了「大棘=稳定记忆」的经典假设，把记忆的物理基础从「单个突触的大小」改写为「突触群的组织架构」——只要这个接线骨架还在，网络的其余部分可以大幅重塑而记忆不丢。对理解睡眠、低温保护与遗忘机制都有直接含义。</p><p>📎 DOI: <a href="https://doi.org/10.1126/science.aee7004" target="_blank" rel="noreferrer">10.1126/science.aee7004</a></p><h3 id="🧬-真核染色体是「两态系统」-靠体积相变在凝聚与解凝聚之间切换" tabindex="-1">🧬 真核染色体是「两态系统」：靠体积相变在凝聚与解凝聚之间切换 <a class="header-anchor" href="#🧬-真核染色体是「两态系统」-靠体积相变在凝聚与解凝聚之间切换" aria-label="Permalink to &quot;🧬 真核染色体是「两态系统」：靠体积相变在凝聚与解凝聚之间切换&quot;">​</a></h3><p><strong>The eukaryote chromosome, a two-state system with interconversion by a volume phase transition</strong><em>Science（2026-08-13）</em></p><p>斯坦福大学 Roger D. Kornberg 团队指出，凝缩蛋白（condensin）的环挤压只能缩短染色体长度，却解释不了染色质<strong>密度</strong>的上升。他们把真核染色体视为一种离子水凝胶：凝缩态与解凝态是两个分立状态，之间的转换是类似「气—液相变」的体积相变。控制开关是组蛋白尾部与 DNA 之间的离子键——组蛋白乙酰化/去乙酰化负责成键与断键，从而决定异染色质凝聚与常染色质解凝聚。这把染色体 condensation 从「机械挤压」问题改写为「聚合物物理 + 静电」问题，给出了一个可测的相变判据。</p><p>📎 DOI: <a href="https://doi.org/10.1126/science.adz1083" target="_blank" rel="noreferrer">10.1126/science.adz1083</a></p><h3 id="🦟-「化学疫苗接种」-单剂低剂量子孢子-抗疟药即可诱导持久无菌免疫" tabindex="-1">🦟 「化学疫苗接种」：单剂低剂量子孢子 + 抗疟药即可诱导持久无菌免疫 <a class="header-anchor" href="#🦟-「化学疫苗接种」-单剂低剂量子孢子-抗疟药即可诱导持久无菌免疫" aria-label="Permalink to &quot;🦟 「化学疫苗接种」：单剂低剂量子孢子 + 抗疟药即可诱导持久无菌免疫&quot;">​</a></h3><p><strong>Chemovaccination with a late-liver-stage antimalarial induces durable immunity against malaria</strong><em>Science（2026-08-13）</em></p><p>传统子孢子疫苗需在肝期减毒、制造复杂且要高剂量静脉注射。Walter and Eliza Hall Institute 团队换了个思路：只给一剂低剂量伯氏疟原虫子孢子（静脉或蚊虫叮咬），随后用 plasmepsin IX/X 抑制剂（WM382 或 MK-7602）把虫体「卡」在肝期，产生所谓<strong>化学减毒肝期裂殖体（CALM）</strong>，小鼠获得长达 21 个月的无菌免疫。保护由抗 CSP 抗体与 CD8⁺ T 细胞共同承担，后者包含识别 SERA1、RPL6、GAP50、RNT、PHIST、S20、RBP 等多种抗原的肝驻留记忆亚群。WM382 对恶性疟同样有效、PMIX/X 活性位点高度保守，提示这条路线有泛疟原虫潜力，且可借长效注射剂 + 自然蚊媒暴露实现接种。</p><p>📎 DOI: <a href="https://doi.org/10.1126/science.aea7605" target="_blank" rel="noreferrer">10.1126/science.aea7605</a></p><h3 id="⚡-机器学习调成分-织构压电陶瓷打破「永远追不上单晶」的天花板" tabindex="-1">⚡ 机器学习调成分，织构压电陶瓷打破「永远追不上单晶」的天花板 <a class="header-anchor" href="#⚡-机器学习调成分-织构压电陶瓷打破「永远追不上单晶」的天花板" aria-label="Permalink to &quot;⚡ 机器学习调成分，织构压电陶瓷打破「永远追不上单晶」的天花板&quot;">​</a></h3><p><strong>Overcoming the performance ceiling of textured piezoelectric ceramics</strong><em>Science（2026-08-13）</em></p><p>织构陶瓷本应兼得单晶的超高压电性与陶瓷的力学强度、低成本，但几十年努力始终差一大截。西安交通大学电子材料研究实验室团队抓住织构陶瓷相对单晶的独有优势——<strong>成分自由度</strong>——用机器学习在 Sm 掺杂的 PIN–PSN–PT 体系中搜索配方，得到压电系数 d₃₃ = <strong>1720 pC/N</strong>、居里温度 <strong>250 °C</strong> 的织构陶瓷，达到甚至超过主流单晶。原位 XRD 与 Rayleigh 分析表明其高压电性主要来自<strong>本征贡献</strong>而非畴翻转。用该陶瓷做成的压电加速器灵敏度更高、可靠性显著优于单晶版本，直接指向器件级替代。</p><p>📎 DOI: <a href="https://doi.org/10.1126/science.aei0475" target="_blank" rel="noreferrer">10.1126/science.aei0475</a></p><h3 id="🔁-不可逆转变从哪来-生物网络里的「不可逆内核」" tabindex="-1">🔁 不可逆转变从哪来：生物网络里的「不可逆内核」 <a class="header-anchor" href="#🔁-不可逆转变从哪来-生物网络里的「不可逆内核」" aria-label="Permalink to &quot;🔁 不可逆转变从哪来：生物网络里的「不可逆内核」&quot;">​</a></h3><p><strong>The structural origin of irreversible transitions in biological networks</strong><em>PNAS（2026-08-13）</em></p><p>细胞过程常在刺激撤除后仍停留在新状态——不可逆性从何而来、能否逆转，一直是悬而未决的问题。韩国科学技术院（KAIST）生物与脑工程系团队提出 ROOT 方法：在逻辑网络模型中定位对不可逆转变功能负责的反馈环（「不可逆内核」），并给出两类控制策略——在保留不可逆性的前提下把系统推回转变前状态，或直接消除不可逆性本身。在多个生物过程上，ROOT 找出的内核与逆转策略同既有实验和文献一致，为「定量地利用不可逆性调控细胞命运」提供了结构层面的抓手。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2600800123" target="_blank" rel="noreferrer">10.1073/pnas.2600800123</a></p><h2 id="🤖-ai-前沿" tabindex="-1">🤖 AI 前沿 <a class="header-anchor" href="#🤖-ai-前沿" aria-label="Permalink to &quot;🤖 AI 前沿&quot;">​</a></h2><h3 id="🔍-「被放大」不等于「有预测力」-思维模型的推理行为账本" tabindex="-1">🔍 「被放大」不等于「有预测力」：思维模型的推理行为账本 <a class="header-anchor" href="#🔍-「被放大」不等于「有预测力」-思维模型的推理行为账本" aria-label="Permalink to &quot;🔍 「被放大」不等于「有预测力」：思维模型的推理行为账本&quot;">​</a></h3><p><strong>Amplified Does Not Mean Predictive: Reasoning Behaviors in Thinking Models</strong><em>arXiv（2026-08-13）</em></p><p>推理导向的训练会让思维链看起来更「深思」，但未必放大真正与答对相关的行为。作者提出 <strong>Behavioral Lift</strong>：某行为在轨迹中出现与否，正确率变化多少。在 15 个模型、6 个基准（文本 + 视觉语言）上标注 <strong>15,282 条轨迹</strong>，发现系统性的「放大—提升落差」——思考模型大幅放大自我纠错、假设检验等行为，这些行为的 Lift 却不高。这提示用「推理行为出现频率」当模型能力代理指标会失真。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.13760" target="_blank" rel="noreferrer">2608.13760</a></p><h3 id="🧩-解释的多样性-电路级可解释性证据经不起「合法分析变体」" tabindex="-1">🧩 解释的多样性：电路级可解释性证据经不起「合法分析变体」 <a class="header-anchor" href="#🧩-解释的多样性-电路级可解释性证据经不起「合法分析变体」" aria-label="Permalink to &quot;🧩 解释的多样性：电路级可解释性证据经不起「合法分析变体」&quot;">​</a></h3><p><strong>Explanation Multiplicity: Circuit-Level Interpretability Evidence Does Not Survive Defensible Analytic Variation</strong><em>arXiv（2026-08-13）</em></p><p>欧盟 AI Act 要求高风险系统提交决策机理文档，电路发现（circuit discovery）是最成熟的工具。作者预注册了 7 条分析轴的交叉网格（每一档都取自已发表实现），在 GPT-2 small 的间接宾语识别任务上跑 <strong>15,840 组规格</strong>，其中 7,561 组产出了可映射为 Annex IV 条款的声明。结果是：两位都能干的分析师、同一系统、同一工具，只要设置不同，得到的「电路」与由此导出的合规声明就不稳定。这给「机制可解释性可直接作监管证据」这一假设打了个大问号。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.13754" target="_blank" rel="noreferrer">2608.13754</a></p><h3 id="⏳-second-thought-把智能体「等环境」的空窗期用来并行推理" tabindex="-1">⏳ Second Thought：把智能体「等环境」的空窗期用来并行推理 <a class="header-anchor" href="#⏳-second-thought-把智能体「等环境」的空窗期用来并行推理" aria-label="Permalink to &quot;⏳ Second Thought：把智能体「等环境」的空窗期用来并行推理&quot;">​</a></h3><p><strong>Second Thought: Reasoning in Parallel as LLM Agents Act and Observe</strong><em>arXiv（2026-08-13）</em></p><p>ReAct 范式里推理只发生在 Thought 阶段；一旦序列化出动作、等待环境返回，推理就被冻住。作者把这个区间命名为 <strong>reasoning idle window</strong>，提出免训练框架 Second Thought：每个 Thought 结束时立刻分叉出 4 条辅助分支，与主循环并发解码，等观测到达时把生成的思考合并回主线程。等于把额外推理搬离主线程的顺序解码路径，在不改权重的前提下用「等待时间」换推理深度。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.13667" target="_blank" rel="noreferrer">2608.13667</a></p><h3 id="📣-adsworldengine-编排器与工具共同演化的自演化对话广告智能体" tabindex="-1">📣 AdsWorldEngine：编排器与工具共同演化的自演化对话广告智能体 <a class="header-anchor" href="#📣-adsworldengine-编排器与工具共同演化的自演化对话广告智能体" aria-label="Permalink to &quot;📣 AdsWorldEngine：编排器与工具共同演化的自演化对话广告智能体&quot;">​</a></h3><p><strong>AdsWorldEngine: A Self-Evolving Conversational Advertising Agent through Orchestrator and Tool Coevolution</strong><em>arXiv（2026-08-13）</em></p><p>对话式广告要从当前 query、助手回复与对话历史中推断<strong>潜在商业意图</strong>，还要判断广告是帮忙还是打扰。AdsWorldEngine 由三部分组成：<strong>Opportunity Gate</strong>（是否该出广告）、<strong>Orchestrator</strong>（生成商业意图、调用广告工具、构造 top-3 广告位）、<strong>Evaluator</strong>（离线打分用于优化）。其核心贡献是 actor–tool 的迭代共同演化——智能体的行为改进会反过来推动工具演化，形成闭环。这类「自演化」结构对把广告从检索式升级为对话式有直接工程价值。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.13833" target="_blank" rel="noreferrer">2608.13833</a></p><h3 id="⚡-sage-用注意力熵调代理梯度斜率-训练脉冲-transformer" tabindex="-1">⚡ SAGE：用注意力熵调代理梯度斜率，训练脉冲 Transformer <a class="header-anchor" href="#⚡-sage-用注意力熵调代理梯度斜率-训练脉冲-transformer" aria-label="Permalink to &quot;⚡ SAGE：用注意力熵调代理梯度斜率，训练脉冲 Transformer&quot;">​</a></h3><p><strong>SAGE: Surrogate-gradient Adaptation via Attention-Guided Entropy for Spiking Transformers</strong><em>arXiv（2026-08-13）</em></p><p>脉冲神经网络靠稀疏事件驱动计算省能，但脉冲函数不可导，只能借代理梯度训练，而固定形状的代理梯度在各层、各训练阶段未必合适。SAGE 从归一化自注意力熵估计<strong>块级不确定性</strong>，用这个信号在训练中动态调整代理梯度斜率；推理模型与部署成本完全不变。这是一种「只改训练时的一个参数」的极低成本改进路径，也把脉冲网络训练与不确定性估计联系了起来。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2608.13702" target="_blank" rel="noreferrer">2608.13702</a></p><blockquote><p>📅 日期：2026-08-13 ｜ ⚠️ 事后重建版 ｜ 📂 科学前沿 5 篇 | 🤖 AI前沿 5 篇</p></blockquote>',45)])])}const u=r(n,[["render",i]]);export{p as __pageData,u as default};
